package bench

import (
	"context"
	"crypto/tls"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"runtime/debug"
	"slices"
	"strings"
	"sync"
	"time"

	formatcfg "github.com/go-git/go-git/v6/plumbing/format/config"
)

// Runner drives one target through concurrency levels of one workload. The
// caller owns the sweep loop: it calls RunLevel once per level, so level
// lifecycle (start/end, the returned LevelResult) is the caller's to observe —
// the engine only reports per-operation samples, via the optional Sink.
type Runner struct {
	target Target
	w      Workload
	creds  credentialProvider
	ep     *endpoint
	httpc  *http.Client
	sink   Sink

	tokenExp   time.Time // zero: not a JWT, the server decides
	levelsLeft int       // levels not yet started
}

// NewRunner resolves a target (credentials + endpoint; for entiredb this
// probes the cluster) and validates the workload against it. sink may be nil.
func NewRunner(ctx context.Context, t Target, w Workload, sink Sink) (*Runner, error) {
	if err := w.Validate(); err != nil {
		return nil, err
	}
	if len(t.Repos) == 0 {
		return nil, errors.New("no repos: pass -repos or -repo-pattern + -repo-count")
	}
	if w.Strategy == "repo" && len(t.Repos) < 2 {
		return nil, errors.New("strategy=repo needs >= 2 repos")
	}
	if t.Secret == "" {
		return nil, errors.New("no credential secret provided")
	}
	httpc := newHTTPClient(t.Insecure, slices.Max(w.Concurrency)+8)

	var (
		creds credentialProvider
		ep    *endpoint
		err   error
	)
	if t.TokenURL != "" || t.Jurisdiction != "" {
		// Go forwards Authorization on same-domain redirects, which would
		// carry the account access token past pinReplicas on any request.
		// The discovery probe vets its own redirect.
		httpc = refuseRedirects(httpc)
		creds, ep, err = setupEntiredb(ctx, t, httpc)
	} else {
		creds, ep, err = setupGeneric(t)
	}
	if err != nil {
		httpc.CloseIdleConnections() // drop the discovery probe's pool
		return nil, err
	}
	r := &Runner{target: t, w: w, creds: creds, ep: ep, httpc: httpc, sink: sink, levelsLeft: len(w.Concurrency)}
	if t.TokenURL != "" || t.Jurisdiction != "" {
		// Only Entire's account token bounds the run. After discovery, so
		// its time counts against the token.
		r.tokenExp, _ = jwtExpiry(t.Secret)
		if err := r.tokenCovers(time.Now()); err != nil {
			r.Close()
			return nil, err
		}
	}
	return r, nil
}

// Label is the resolved endpoint label (the remote base URL), for banners and
// results.
func (r *Runner) Label() string { return r.ep.label }

// Nodes is how many push destinations the endpoint fans out across (1 for any
// plain forge; the discovered replica count for entiredb).
func (r *Runner) Nodes() int { return len(r.ep.nodes) }

// ObjectFormat is the resolved wire object format ("sha1" or "sha256").
func (r *Runner) ObjectFormat() string { return string(r.ep.objFmt) }

// Close releases the runner's resources once its run is over: it drops idle
// keep-alive connections and severs the runner's reference to the credential
// provider, so the credential (a PAT, or an Entire subject/access token) held
// for the run becomes eligible for garbage collection instead of living on in a
// finished run kept resident in memory. Go strings can't be wiped in place, so
// dropping the reference is the strongest release available.
func (r *Runner) Close() {
	// Stop any background token refresh before dropping the reference, or a
	// detached exchange could keep running (and holding the token) after the run.
	if c, ok := r.creds.(credentialCloser); ok {
		c.close()
	}
	if r.httpc != nil {
		r.httpc.CloseIdleConnections()
	}
	r.creds = nil
	r.target.Secret = "" // drop the runner's own copy of the token
}

// credentialCloser is an optional credentialProvider capability: release any
// background machinery and the credentials it holds.
type credentialCloser interface{ close() }

// StartBarrier synchronizes the start of one concurrency level across several
// runners: each Arrives once its agents are built, and the coordinator
// releases them together, so target-dependent setup time can't skew the
// measured windows of a comparison run. It tolerates a runner that fails
// before it is ready — that runner still Arrives, so Await can't hang. A nil
// barrier means "run alone, no synchronization" (the CLI's single-target path).
type StartBarrier struct {
	arrived chan struct{}
	release chan struct{}
	n       int
	firedAt time.Time // set before release closes; the shared start instant
}

// NewStartBarrier makes a barrier expecting n participants.
func NewStartBarrier(n int) *StartBarrier {
	return &StartBarrier{arrived: make(chan struct{}, n), release: make(chan struct{}), n: n}
}

// Arrive reports that this participant has finished preparing (or has given up
// and won't Hold). The buffered channel makes it non-blocking.
func (b *StartBarrier) Arrive() { b.arrived <- struct{}{} }

// Hold blocks until the coordinator fires the shared start signal.
func (b *StartBarrier) Hold() { <-b.release }

// Await blocks until every participant has Arrived.
func (b *StartBarrier) Await() {
	for i := 0; i < b.n; i++ {
		<-b.arrived
	}
}

// Fire releases every held participant to begin its timed window together. It
// stamps firedAt before closing release, so every participant and the
// coordinator share one start instant (via FiredAt) rather than each reading
// its own time.Now after being scheduled — which would skew the sample clock
// against the window/dt_ms timestamps. The close is a happens-before edge, so
// the write is visible to every Hold() that returns.
func (b *StartBarrier) Fire() {
	b.firedAt = time.Now()
	close(b.release)
}

// FiredAt is the shared start instant, valid after Fire (for the coordinator) or
// after Hold returns (for a participant).
func (b *StartBarrier) FiredAt() time.Time { return b.firedAt }

// RunLevel runs a single concurrency level: build c agents, wait at the
// barrier so all targets start together, run for warmup+duration, then fold
// the samples into one result. It blocks for the full level window (or until
// ctx is cancelled). barrier may be nil to run without synchronization.
func (r *Runner) RunLevel(ctx context.Context, c int, barrier *StartBarrier) (LevelResult, error) {
	var clone *cloneConfig
	var sess *sessionConfig
	switch r.w.Strategy {
	case "clone":
		clone = &cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef}
	case "session":
		sess = &sessionConfig{
			cloneConfig: cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef},
			commits:     r.w.SessionCommits,
		}
	}
	agents := make([]*agent, c)
	for i := range c {
		repoPath := r.target.Repos[0]
		if r.w.Strategy == "repo" {
			repoPath = r.target.Repos[i%len(r.target.Repos)]
		}
		node := r.ep.nodes[i%len(r.ep.nodes)]
		ref := DestRef(r.w.Namespace(), r.w.BranchPrefix, r.w.RunID, c, i)
		a, err := newAgent(i, repoPath, node, ref, r.ep.objFmt, &r.w.Commit, r.creds, r.httpc, clone, sess, r.sink)
		if err != nil {
			if barrier != nil {
				barrier.Arrive() // don't leave the coordinator's Await hanging
			}
			return LevelResult{}, fmt.Errorf("new agent %d: %w", i, err)
		}
		agents[i] = a
	}

	// Agents are built; wait for every target before starting the clock, so the
	// measured window begins at the same instant on each and the comparison is
	// fair regardless of per-target setup time.
	if barrier != nil {
		barrier.Arrive()
		barrier.Hold()
	}

	total := r.w.Warmup + r.w.Duration
	// Origin the sample clock AND the context deadline on the same instant — the
	// barrier's shared fire time when there is one. Using FiredAt for the offset
	// origin but a scheduled-now timeout for the deadline let a target released
	// late run a full `total` from its late start, recording samples past the
	// shared window end that summarize then miscounts against the fixed duration.
	// Deriving the deadline from FiredAt()+total stops every target together.
	// Single-target CLI runs have no barrier and just start now.
	start := time.Now()
	if barrier != nil {
		start = barrier.FiredAt()
	}
	// Recheck at the window: discovery, agent setup, the barrier and the
	// previous level's cleanup all spent token lifetime.
	if err := r.tokenCovers(start); err != nil {
		return LevelResult{}, err
	}
	r.levelsLeft = max(r.levelsLeft-1, 0)
	lvlCtx, cancel := context.WithDeadline(ctx, start.Add(total))
	defer cancel()
	var wg sync.WaitGroup
	for _, a := range agents {
		wg.Add(1)
		go func(a *agent) {
			defer wg.Done()
			a.run(lvlCtx, start)
		}(a)
	}
	wg.Wait()

	var all []Sample
	for _, a := range agents {
		all = append(all, a.samples...)
	}
	reposUsed := 1
	if r.w.Strategy == "repo" {
		reposUsed = min(c, len(r.target.Repos))
	}
	return summarize(all, c, r.w.Strategy, reposUsed, len(r.ep.nodes), r.w.Warmup, r.w.Duration, r.w.CommitDesc()), nil
}

func setupGeneric(t Target) (credentialProvider, *endpoint, error) {
	if t.Remote == "" {
		return nil, nil, errors.New("-remote required (e.g. https://gitlab.com); for entiredb also pass -token-url and -jurisdiction")
	}
	if IsGitHubDotCom(t.Remote) && t.ObjectFmt == "sha256" {
		return nil, nil, errors.New("github.com is sha1; drop -object-format sha256")
	}
	objFmt, err := parseObjectFormat(t.ObjectFmt)
	if err != nil {
		return nil, nil, err
	}
	user := t.User
	if user == "" {
		user = "x-access-token" // token forges ignore the username; the token is the password
	}
	return staticCreds{username: user, password: t.Secret}, newGenericEndpoint(t.Remote, objFmt), nil
}

// tokenCovers refuses to start work the account access token cannot
// cover: nothing refreshes it, so a level that outlives it would report
// authentication failures as throughput. It needs every level not yet
// started, plus session ref cleanup after each window and clock skew,
// measured from now. A secret that is not a JWT with exp passes.
func (r *Runner) tokenCovers(now time.Time) error {
	if r.tokenExp.IsZero() {
		return nil
	}
	levels := max(r.levelsLeft, 1)
	var cleanup time.Duration
	if r.w.Strategy == "session" {
		cleanup = sessionCleanupTimeout
	}
	need := time.Duration(levels)*(r.w.Warmup+r.w.Duration+cleanup) + tokenSkew
	if left := r.tokenExp.Sub(now); left < need {
		return fmt.Errorf("token expires in %s but %d remaining levels need %s (warmup %s + duration %s + cleanup %s each, + %s skew); mint a fresher token or shorten the run",
			max(left, 0).Round(time.Second), levels, need, r.w.Warmup, r.w.Duration, cleanup, tokenSkew)
	}
	return nil
}

// tokenSkew absorbs clock drift against the issuer.
const tokenSkew = 30 * time.Second

// jwtExpiry reads exp from an unverified JWT payload.
func jwtExpiry(token string) (time.Time, bool) {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return time.Time{}, false
	}
	payload, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return time.Time{}, false
	}
	var c struct {
		Exp int64 `json:"exp"`
	}
	if json.Unmarshal(payload, &c) != nil || c.Exp == 0 {
		return time.Time{}, false
	}
	return time.Unix(c.Exp, 0), true
}

// refuseRedirects returns a copy of c (same transport and pool) that fails
// every redirect instead of following it.
func refuseRedirects(c *http.Client) *http.Client {
	out := *c
	out.CheckRedirect = func(*http.Request, []*http.Request) error {
		return errors.New("entiredb request attempted a redirect; refusing to forward the credential")
	}
	return &out
}

func setupEntiredb(ctx context.Context, t Target, httpc *http.Client) (credentialProvider, *endpoint, error) {
	var missing []string
	if t.Remote == "" {
		missing = append(missing, "-remote (cluster base URL)")
	}
	if t.TokenURL == "" {
		missing = append(missing, "-token-url")
	}
	if t.Jurisdiction == "" {
		missing = append(missing, "-jurisdiction")
	}
	if len(missing) > 0 {
		return nil, nil, fmt.Errorf("entire target (selected by -token-url/-jurisdiction) also needs: %s", strings.Join(missing, ", "))
	}
	// The subject token is the account access token; entiredb authorizes each
	// push live on its subject, so it is presented as-is (ADR 20260729).
	// Entire ignores the username.
	creds := staticCreds{username: "token", password: t.Secret}
	ep, err := newEntireEndpoint(ctx, t.Remote, t.ObjectFmt, t.Repos[0], creds, httpc)
	if err != nil {
		return nil, nil, err
	}
	return creds, ep, nil
}

func parseObjectFormat(s string) (formatcfg.ObjectFormat, error) {
	switch s {
	case "sha256":
		return formatcfg.SHA256, nil
	case "sha1", "auto", "": // generic doesn't probe; auto degrades to sha1
		return formatcfg.SHA1, nil
	default:
		return "", fmt.Errorf("invalid -object-format %q (sha1|sha256|auto)", s)
	}
}

func newHTTPClient(insecure bool, maxConns int) *http.Client {
	tr := &http.Transport{
		Proxy:               http.ProxyFromEnvironment,
		MaxIdleConns:        maxConns * 2,
		MaxIdleConnsPerHost: maxConns,
		MaxConnsPerHost:     0, // unbounded: don't queue pushes behind a conn cap
		IdleConnTimeout:     90 * time.Second,
	}
	if insecure {
		tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true} //nolint:gosec // load-test opt-in
	}
	// Client.Timeout must stay zero: with a wrapped RoundTripper a nonzero
	// value falls off net/http's known-transport fast path and spawns a
	// cancellation goroutine per request, skewing the very operations
	// forgemark measures. uaTransport enforces the timeout instead.
	return &http.Client{Transport: &uaTransport{base: tr, timeout: 120 * time.Second}}
}

// uaToken identifies forgemark in User-Agent headers. Binaries built from a
// git checkout carry the commit via Go's embedded VCS info, so server logs can
// tie traffic to an exact revision — with "-dirty" when the tree had
// uncommitted changes; otherwise (go test, -buildvcs=off) it's the bare name.
var uaToken = func() string {
	bi, ok := debug.ReadBuildInfo()
	if !ok {
		return "forgemark"
	}
	var revision, dirty string
	for _, s := range bi.Settings {
		switch s.Key {
		case "vcs.revision":
			revision = s.Value
			if len(revision) > 12 {
				revision = revision[:12]
			}
		case "vcs.modified":
			if s.Value == "true" {
				dirty = "-dirty"
			}
		}
	}
	if revision == "" {
		return "forgemark"
	}
	return "forgemark/" + revision + dirty
}()

// uaTransport appends uaToken to every request's User-Agent so server logs can
// attribute load-test traffic. Appending keeps go-git's agent string first
// (servers may key protocol behavior on it), and tagging only the HTTP header
// leaves the git protocol's agent capability untouched — go-git's
// GO_GIT_USER_AGENT_EXTRA hook would land there too, where the embedded space
// reads as a bogus extra capability, and would leak into subprocess
// environments.
//
// It also imposes the request timeout as a context deadline (see
// newHTTPClient). Unlike Client.Timeout the budget is per attempt, not per
// redirect chain; forgemark's endpoints don't redirect, so that difference is
// theoretical.
type uaTransport struct {
	base    *http.Transport
	timeout time.Duration
}

func (t *uaTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	// Per the RoundTripper contract, don't mutate the caller's request.
	ctx, cancel := context.WithTimeout(req.Context(), t.timeout)
	req = req.Clone(ctx)
	if ua := req.Header.Get("User-Agent"); ua != "" {
		req.Header.Set("User-Agent", ua+" "+uaToken)
	} else {
		req.Header.Set("User-Agent", uaToken)
	}
	resp, err := t.base.RoundTrip(req)
	if err != nil {
		cancel()
		return nil, err
	}
	// Like Client.Timeout, the deadline covers reading the body; the timer is
	// released when the caller closes it.
	resp.Body = &cancelOnClose{ReadCloser: resp.Body, cancel: cancel}
	return resp, nil
}

// CloseIdleConnections forwards to the underlying transport; without it,
// http.Client.CloseIdleConnections (used by run cleanup) would be a no-op.
func (t *uaTransport) CloseIdleConnections() { t.base.CloseIdleConnections() }

type cancelOnClose struct {
	io.ReadCloser
	cancel context.CancelFunc
}

func (b *cancelOnClose) Close() error {
	b.cancel()
	return b.ReadCloser.Close()
}

package bench

import (
	"context"
	"errors"
	"fmt"
	"io"
	"math/rand"
	"net/http"
	"regexp"
	"strings"
	"time"

	"github.com/go-git/go-billy/v6/memfs"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/config"
	gitclient "github.com/go-git/go-git/v6/plumbing/client"
	formatcfg "github.com/go-git/go-git/v6/plumbing/format/config"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/storage/memory"
)

// noopSigner skips commit signing so the host's commit.gpgsign config never
// interferes.
type noopSigner struct{}

func (noopSigner) Sign(context.Context, io.Reader) ([]byte, error) { return nil, nil }

// agent is one synthetic writer. It keeps an in-memory git repo and pushes a
// stream of small commits to its assigned ref on its assigned repo+node. Each
// agent owns its own ref (per-agent branch), so in branch/repo strategies its
// pushes never lose a CAS race — what we measure is the server's per-repo
// serialized ref-commit throughput, not client retry behaviour.
type agent struct {
	id       int
	repoPath string // repo path, appended to node verbatim (see verbatimURLFor)
	node     string // node base URL, e.g. https://node1.cluster:443
	ref      string // destination ref, e.g. refs/forgemark/<run>-c8-a7 (see DestRef)
	objFmt   formatcfg.ObjectFormat

	cfg   *CommitConfig
	creds credentialProvider
	httpc *http.Client
	clone *cloneConfig   // non-nil → "clone" strategy (clone-only loop)
	sess  *sessionConfig // non-nil → "session" strategy (clone+push loop)
	sink  Sink           // optional live observer; nil on the CLI path

	repo    *git.Repository
	samples []Sample
}

// record appends a sample to the agent's authoritative post-hoc log and, when
// a sink is attached, forwards it live. Every sample the agent takes goes
// through here.
func (a *agent) record(s Sample) {
	a.samples = append(a.samples, s)
	if a.sink != nil {
		a.sink.OnSample(s)
	}
}

// CommitConfig is the subset of run config an agent needs.
type CommitConfig struct {
	FilesMin int
	FilesMax int
	FileSize int
}

// authorEmail stamps the synthetic load commits. .invalid is the RFC 2606
// reserved TLD, so it can never collide with a real address.
const authorEmail = "agent@forgemark.invalid"

// resetEvery re-initialises an agent's in-memory repo after this many commits.
// memory.NewStorage keeps every object it ever wrote, so a long sweep would
// grow unbounded (each commit adds fresh random blobs); re-init caps retained
// history. Each agent force-pushes its own ref, so a fresh orphan line is fine.
const resetEvery = 128

// newAgent builds an agent. In branch/repo mode it initialises its in-memory
// repo up front (object format matched to the remote). In clone/session mode
// the repo is created per clone by the clone loop, so init is skipped.
func newAgent(id int, repoPath, node, ref string, objFmt formatcfg.ObjectFormat, cfg *CommitConfig, creds credentialProvider, httpc *http.Client, clone *cloneConfig, sess *sessionConfig, sink Sink) (*agent, error) {
	a := &agent{
		id: id, repoPath: repoPath, node: node, ref: ref, objFmt: objFmt,
		cfg: cfg, creds: creds, httpc: httpc, clone: clone, sess: sess, sink: sink,
	}
	if clone == nil && sess == nil {
		if err := a.initRepo(); err != nil {
			return nil, err
		}
	}
	return a, nil
}

// initRepo (re)creates the agent's in-memory repo and origin remote, dropping
// any accumulated objects from a previous generation.
func (a *agent) initRepo() error {
	repo, err := git.Init(memory.NewStorage(),
		git.WithWorkTree(memfs.New()),
		git.WithObjectFormat(a.objFmt),
	)
	if err != nil {
		return fmt.Errorf("git init: %w", err)
	}
	if _, err := repo.CreateRemote(&config.RemoteConfig{
		Name: "origin",
		URLs: []string{verbatimURLFor(a.node, a.repoPath)},
	}); err != nil {
		return fmt.Errorf("create remote: %w", err)
	}
	a.repo = repo
	return nil
}

// run dispatches the agent's configured strategy until ctx is cancelled.
// start anchors sample offsets so the caller can drop the warm-up window
// afterwards.
func (a *agent) run(ctx context.Context, start time.Time) {
	if a.clone != nil {
		a.runClones(ctx, start)
		return
	}
	if a.sess != nil {
		a.runSessions(ctx, start)
		return
	}
	rng := rand.New(rand.NewSource(int64(a.id)*1_000_003 + 1)) //nolint:gosec // synthetic load content, not security-sensitive
	iter := 0
	for ctx.Err() == nil {
		if iter > 0 && iter%resetEvery == 0 {
			if err := a.initRepo(); err != nil {
				a.record(Sample{Offset: time.Since(start), Res: OutcomeErr, Msg: err.Error()})
				iter++
				continue
			}
		}
		if err := a.commit(rng, iter); err != nil {
			// A local commit failure is a harness bug, not a server signal —
			// record it as an error and keep going so one bad agent doesn't
			// silently drop out of the concurrency level.
			a.record(Sample{Offset: time.Since(start), Res: OutcomeErr, Msg: err.Error()})
			iter++
			continue
		}
		t0 := time.Now()
		err := a.push(ctx)
		dur := time.Since(t0)
		// Don't record the attempt that lost the ctx-cancellation race; it's a
		// truncated measurement, not real latency.
		if ctx.Err() != nil {
			break
		}
		o := classify(err)
		a.record(Sample{Offset: t0.Sub(start), Dur: dur, Res: o, Msg: errMsg(o, err)})
		iter++
	}
}

// commit writes FilesMin..FilesMax small files and records a commit on the
// local default branch (refs/heads/master). Stable filenames mean later commits
// are modifications, the realistic shape of an agent editing a working set.
func (a *agent) commit(rng *rand.Rand, iter int) error {
	wt, err := a.repo.Worktree()
	if err != nil {
		return fmt.Errorf("worktree: %w", err)
	}
	n := a.cfg.FilesMin
	if a.cfg.FilesMax > a.cfg.FilesMin {
		n += rng.Intn(a.cfg.FilesMax - a.cfg.FilesMin + 1)
	}
	buf := make([]byte, a.cfg.FileSize)
	for i := range n {
		name := fmt.Sprintf("file-%d.txt", i)
		f, err := wt.Filesystem().Create(name)
		if err != nil {
			return fmt.Errorf("create %s: %w", name, err)
		}
		_, _ = rng.Read(buf) // math/rand never errors; random bytes → distinct blob
		if _, err := f.Write(buf); err != nil {
			_ = f.Close()
			return fmt.Errorf("write %s: %w", name, err)
		}
		_ = f.Close()
		if _, err := wt.Add(name); err != nil {
			return fmt.Errorf("add %s: %w", name, err)
		}
	}
	sig := &object.Signature{
		Name:  fmt.Sprintf("agent-%d", a.id),
		Email: authorEmail,
		When:  time.Now(),
	}
	if _, err := wt.Commit(fmt.Sprintf("agent %d commit %d", a.id, iter),
		&git.CommitOptions{Author: sig, Signer: noopSigner{}}); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

func (a *agent) push(ctx context.Context) error {
	auth, err := a.creds.basicAuth(ctx, a.repoPath)
	if err != nil {
		return err
	}
	err = a.repo.PushContext(ctx, &git.PushOptions{
		RemoteName: "origin",
		RefSpecs:   []config.RefSpec{config.RefSpec("+refs/heads/master:" + a.ref)},
		Force:      true, // each agent owns its ref; force keeps numbers clean of spurious non-ff
		ClientOptions: []gitclient.Option{
			gitclient.WithHTTPClient(a.httpc),
			gitclient.WithHTTPAuth(auth),
		},
	})
	if err != nil {
		return fmt.Errorf("push: %w", err)
	}
	return nil
}

// classify maps a push result to an Outcome. A nil error or "already
// up-to-date" is success; a CAS / non-fast-forward rejection is contention;
// everything else is an error.
func classify(err error) Outcome {
	switch {
	case err == nil, errors.Is(err, git.NoErrAlreadyUpToDate):
		return OutcomeOK
	case errors.Is(err, git.ErrNonFastForwardUpdate):
		return OutcomeCAS
	default:
		msg := strings.ToLower(err.Error())
		if strings.Contains(msg, "non-fast-forward") ||
			strings.Contains(msg, "reference has changed") ||
			strings.Contains(msg, "fetch first") ||
			strings.Contains(msg, "stale info") {
			return OutcomeCAS
		}
		return OutcomeErr
	}
}

// maxErrMsgLen caps a retained error message. Longer messages are truncated
// after normalization so a long URL can't crowd the signal out of the window.
const maxErrMsgLen = 200

// reURL/reRef match the volatile substrings go-git embeds in error text — the
// receive-pack URL (varies by node/repo) and the destination ref (varies by
// agent/session, and by namespace: refs/forgemark/ by default, refs/heads/ or
// anything else via -ref-namespace). Collapsing them lets identical failures
// group in the results. Compiled once; the message-shape sibling of classify.
var (
	reURL = regexp.MustCompile(`https?://\S+`)
	reRef = regexp.MustCompile(`refs/\S+`)
)

// normalizeErr turns a raw go-git error message into a stable grouping key:
// collapse this run's volatile URLs/refs, then truncate. Order matters —
// truncating first could cut the status code that follows a long URL.
func normalizeErr(msg string) string {
	if msg == "" {
		return "(no message)"
	}
	msg = reURL.ReplaceAllString(msg, "<url>")
	msg = reRef.ReplaceAllString(msg, "<ref>")
	if len(msg) > maxErrMsgLen {
		msg = msg[:maxErrMsgLen]
	}
	return msg
}

// Package bench is the forgemark benchmark engine: it drives real git
// push/clone operations against one target forge and reports per-level
// results. Frontends (the CLI, and any interactive UI) are thin layers over
// Runner; they observe a run live through the exported Sink.
package bench

import (
	"errors"
	"fmt"
	"net/url"
	"strconv"
	"strings"
	"time"

	"github.com/go-git/go-git/v6/plumbing"
)

// Target is one forge to benchmark: where to connect and how to authenticate.
// Supplying TokenURL or Jurisdiction selects the entiredb path (node
// discovery, account access token presented directly); they mean nothing to
// any other forge, so their presence is the signal — no separate target-kind
// field.
type Target struct {
	Name      string   // display label; empty defaults to the remote base URL
	Remote    string   // base URL of the forge, e.g. https://gitlab.com
	Repos     []string // repo paths appended to Remote verbatim
	User      string   // basic-auth username (default x-access-token; token forges ignore it)
	Secret    string   `json:"-"` // credential secret (forge token, or the entiredb account access token); json:"-" so no marshal path can ever leak it
	Insecure  bool     // skip TLS verification
	ObjectFmt string   // "auto" | "sha1" | "sha256"

	// entiredb. Presence selects the path; none of the three is dialed.
	TokenURL     string
	Jurisdiction string
	ClientID     string
}

// Hard safety caps, not tuning suggestions: a single host can't generate a
// meaningful benchmark anywhere near them, and unbounded values from the
// server API would otherwise reach make([]*agent, c), c goroutine spawns,
// and per-sample retention for the whole window — panic/OOM territory.
//
// Known ceiling, deliberately NOT capped: within these limits, retained-sample
// memory still scales with measured throughput (a 6h max-concurrency level
// against a very fast target reaches 10⁸+ Samples). That is the cost of the
// exact percentiles LevelResult promises for real runs — the bounded
// alternative is approximation, which is exactly the trade the demo target
// makes and real results must not. An aggregate agent-hours cap would reject
// valid configs to protect operators from their own machine's RAM; the ops
// have to actually happen for the memory to exist, so the operator is load
// generator and victim at once. If this ever bites in practice, the fix is
// compact retention (durations only, errors grouped online), not a cap here.
const (
	maxConcurrency = 4096          // agents per level
	maxLevels      = 16            // levels per sweep
	maxDuration    = 6 * time.Hour // measured window per level
	maxWarmup      = time.Hour     // warm-up per level

	// Commit content is the same class of API-reachable allocation: FileSize
	// goes straight into make([]byte, FileSize) in every agent (a near-MaxInt
	// value is a runtime panic that kills the whole process, not just the
	// run), and FilesMax × FileSize is the working set every agent keeps in
	// its in-memory worktree.
	maxFilesMax    = 1024     // files per commit
	maxFileSize    = 16 << 20 // bytes per file
	maxCommitBytes = 64 << 20 // files-max × file-size, one commit's payload
)

// Workload is the target-independent shape of a run: strategy, sweep, and
// commit content. One Workload is shared by every target of a comparison run.
type Workload struct {
	RunID        string
	Strategy     string // branch | repo | clone | session
	RefNamespace string // ref namespace pushes land under; "" = DefaultRefNamespace
	BranchPrefix string // prepended verbatim inside the namespace, before the run ID
	Concurrency  []int
	Duration     time.Duration
	Warmup       time.Duration
	Commit       CommitConfig

	// session/clone strategies
	SessionCommits int
	CloneDepth     int
	BaseRef        string
}

// Validate applies the target-independent checks that parseFlags used to do,
// so the server rejects a bad workload with the same errors the CLI reports.
func (w Workload) Validate() error {
	switch w.Strategy {
	case "branch", "repo", "clone", "session":
	default:
		return fmt.Errorf("invalid -strategy %q (branch|repo|clone|session)", w.Strategy)
	}
	if w.Strategy == "session" && w.SessionCommits < 1 {
		return errors.New("-session-commits must be >= 1")
	}
	if w.CloneDepth < 0 {
		return errors.New("-clone-depth must be >= 0 (0 = full history)")
	}
	if len(w.Concurrency) == 0 {
		return errors.New("no concurrency levels")
	}
	if len(w.Concurrency) > maxLevels {
		return fmt.Errorf("too many concurrency levels: %d (max %d)", len(w.Concurrency), maxLevels)
	}
	for _, n := range w.Concurrency {
		if n < 1 || n > maxConcurrency {
			return fmt.Errorf("invalid concurrency %d (must be 1..%d)", n, maxConcurrency)
		}
	}
	if w.Duration <= 0 || w.Duration > maxDuration {
		return fmt.Errorf("-duration must be > 0 and <= %s", maxDuration)
	}
	if w.Warmup < 0 || w.Warmup > maxWarmup {
		return fmt.Errorf("-warmup must be >= 0 and <= %s", maxWarmup)
	}
	if w.Strategy != "clone" {
		if w.Commit.FilesMin < 1 {
			return errors.New("-files-min must be >= 1 (a commit needs a change to push)")
		}
		if w.Commit.FilesMax < w.Commit.FilesMin {
			return errors.New("-files-max < -files-min")
		}
		if w.Commit.FilesMax > maxFilesMax {
			return fmt.Errorf("-files-max must be <= %d", maxFilesMax)
		}
		if w.Commit.FileSize < 1 {
			return errors.New("-file-size must be >= 1 (empty blobs reproduce → ErrEmptyCommit)")
		}
		if w.Commit.FileSize > maxFileSize {
			return fmt.Errorf("-file-size must be <= %d (%dMiB)", maxFileSize, maxFileSize>>20)
		}
		// Both factors already fit comfortably in int64, so the product can't
		// overflow this aggregate check.
		if int64(w.Commit.FilesMax)*int64(w.Commit.FileSize) > maxCommitBytes {
			return fmt.Errorf("-files-max × -file-size must be <= %dMiB per commit", maxCommitBytes>>20)
		}
	}
	// Validate the assembled ref, not the parts alone: validity is context-dependent
	// (a trailing "/" or bare word is fine mid-ref, invalid standalone). c/a are arbitrary —
	// only the namespace and prefix can invalidate it — so these parse-time checks cover
	// the whole sweep. The namespace is checked first, on its own, so a bad namespace
	// isn't reported as a bad prefix.
	runID := w.RunID
	if runID == "" {
		runID = "fmX"
	}
	ns := w.Namespace()
	if !strings.HasPrefix(ns, "refs/") || ns == "refs/" {
		return fmt.Errorf("invalid -ref-namespace %q: must be refs/<name>/", w.RefNamespace)
	}
	if err := plumbing.ReferenceName(DestRef(ns, "", runID, 1, 0)).Validate(); err != nil {
		return fmt.Errorf("invalid -ref-namespace %q: %w", w.RefNamespace, err)
	}
	if err := plumbing.ReferenceName(DestRef(ns, w.BranchPrefix, runID, 1, 0)).Validate(); err != nil {
		return fmt.Errorf("invalid -branch-prefix %q: %w", w.BranchPrefix, err)
	}
	return nil
}

// DefaultRefNamespace is where bench refs land unless -ref-namespace says
// otherwise. It is deliberately NOT refs/heads/: receive-pack does the same
// work for any ref (pack unpack, connectivity check, ref CAS), but a branch
// additionally triggers whatever the forge runs post-receive — search
// ingestion, CI, webhooks, branch UI — which costs money and rate-limit
// budget on the target and is invisible to the push latency this tool
// measures anyway. A private namespace keeps every forge's post-receive
// pipeline out of the loop, and the comparison apples to apples. Override
// with refs/heads/ to load that pipeline on purpose.
const DefaultRefNamespace = "refs/forgemark/"

// Namespace returns the effective ref namespace: DefaultRefNamespace when
// unset, always with exactly one trailing slash so DestRef can concatenate.
func (w Workload) Namespace() string {
	ns := w.RefNamespace
	if ns == "" {
		return DefaultRefNamespace
	}
	return strings.TrimRight(ns, "/") + "/"
}

// CommitDesc describes the commit content shape, e.g. "1-10 x 2048B".
func (w Workload) CommitDesc() string {
	return fmt.Sprintf("%d-%d x %dB", w.Commit.FilesMin, w.Commit.FilesMax, w.Commit.FileSize)
}

// NewRunID returns a fresh run identifier. Nanosecond resolution so two runs
// started back-to-back (a server restarting a sweep) can't collide.
func NewRunID() string {
	return "fm" + strconv.FormatInt(time.Now().UnixNano(), 36)
}

// DestRef builds an agent's destination ref under namespace (already
// normalized by Workload.Namespace, trailing slash included), prepending
// branchPrefix verbatim before the run ID. Empty prefix reproduces the
// default name.
func DestRef(namespace, branchPrefix, runID string, c, i int) string {
	return fmt.Sprintf("%s%s%s-c%d-a%d", namespace, branchPrefix, runID, c, i)
}

// IsGitHubDotCom reports whether remote points at github.com (so the abuse
// warning + sha1 constraint apply). Any other host — GHES, GitLab, Gitea — is
// just a generic forge.
func IsGitHubDotCom(remote string) bool {
	u, err := url.Parse(remote)
	if err != nil {
		return false
	}
	return strings.EqualFold(u.Hostname(), "github.com")
}

