// unbounded growth. Once per second the run's ticker calls snapshot, which
// rotates the current second into the ring and computes rolling percentiles
// from the windowed histograms.
type collector struct {
	mu        sync.Mutex
	warmup    time.Duration // samples before this offset are excluded (matches the level result)
	cur       bucket
	ring      [windowSecs]latHist // one closed second of OK push latencies per slot
	cloneRing [windowSecs]latHist
	pos       int
}

// bucket accumulates one second of samples.
type bucket struct {
	ok, cas, errs     int
	cloneOK, cloneErr int
	lat               latHist // OK push latencies (ms)
	cloneLat          latHist // OK clone latencies (ms)
}

// BucketStats is one target's slice of a per-second bucket event. Push and
// clone ops are reported separately, mirroring LevelResult; the UI picks the
// primary series from the workload strategy. Attempt totals are derivable
// (ok+cas+err, clone_ok+clone_err), so they aren't carried on the wire.
type BucketStats struct {
	OK  int `json:"ok"`
	CAS int `json:"cas"`
	Err int `json:"err"`
	// Rolling percentiles over the last windowSecs seconds of OK pushes.
	P50 float64 `json:"p50_ms"`
	P95 float64 `json:"p95_ms"`
	P99 float64 `json:"p99_ms"`

	CloneOK  int     `json:"clone_ok,omitempty"`
	CloneErr int     `json:"clone_err,omitempty"`
	CloneP50 float64 `json:"clone_p50_ms,omitempty"`
	CloneP95 float64 `json:"clone_p95_ms,omitempty"`
	CloneP99 float64 `json:"clone_p99_ms,omitempty"`
}

func (c *collector) OnSample(s bench.Sample) {
	// The bucket index (a math.Log) is computed before taking the lock, so the
	// critical section is nothing but integer increments — the sink must not
	// serialize the agents whose throughput it is observing.
	idx := latHistIdx(float64(s.Dur) / float64(time.Millisecond))
	c.mu.Lock()
	defer c.mu.Unlock()
	// The Sink receives warm-up samples too; drop them so the live counts,
	// rolling percentiles, and persisted series match the authoritative level
	// result, which excludes the warm-up window.
	if s.Offset < c.warmup {
		return
	}
	if s.Op == bench.OpClone {
		switch s.Res {
		case bench.OutcomeOK:
			c.cur.cloneOK++
			c.cur.cloneLat[idx]++
		default:
			c.cur.cloneErr++
		}
	u := float64(c) / d.p50.Seconds() / d.cap
	return math.Sqrt(math.Sqrt(1 + u*u*u*u))
}

func (d *demoRunner) RunLevel(ctx context.Context, c int, barrier *bench.StartBarrier) (bench.LevelResult, error) {
	inflate := d.saturationInflate(c)

	// Wait for the shared start so the demo target's window aligns with the
	// real targets it's compared against.
	if barrier != nil {
		barrier.Arrive()
		barrier.Hold()
	}

	// Origin both the deadline and the sample clock on the barrier's shared fire
	// instant, exactly like bench.Runner, so scheduler delay after release can't
	// shift or extend the demo's window past the real targets it races against
	// (which would give it extra ops and make live buckets disagree with the
	// final result).
	total := d.w.Warmup + d.w.Duration
	start := time.Now()
	if barrier != nil {
		start = barrier.FiredAt()
	}
	lctx, cancel := context.WithDeadline(ctx, start.Add(total))
	defer cancel()
	agg := &demoAgg{warmup: d.w.Warmup}
	var wg sync.WaitGroup
	for i := range c {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			// Deterministic per agent, like the engine's commit content rng.
			rng := rand.New(rand.NewSource(int64(id)*7919 + 42)) //nolint:gosec // synthetic demo data
			pushesLeft := 0                                      // session state: pushes remaining before the next clone
			for lctx.Err() == nil {
				lat := d.sampleLatency(rng, inflate)
				t0 := time.Now()
				select {
				case <-time.After(lat):
				case <-lctx.Done():
					return // drop the truncated op, like the engine does
				}
				s := bench.Sample{Offset: t0.Sub(start), Dur: time.Since(t0), Op: d.nextOp(pushesLeft)}
				switch roll := rng.Float64(); {
				case roll < d.errRate:
					s.Res = bench.OutcomeErr
					s.Msg = "demo: synthetic error"
				case roll < d.errRate+d.casRate && s.Op == bench.OpPush:
					s.Res = bench.OutcomeCAS // CAS is a ref-update outcome; clones can't CAS
				}
				// Session bookkeeping mirrors runSessions: a successful clone opens a
				// session of SessionCommits pushes; a failed clone retries (pushesLeft
				// stays 0); each push consumes an attempt whatever its outcome.
				if d.w.Strategy == "session" {
					if s.Op == bench.OpClone {
						if s.Res == bench.OutcomeOK {
							pushesLeft = d.w.SessionCommits
						}
					} else {
						pushesLeft--
					}
				}
				if d.sink != nil {
					d.sink.OnSample(s)
				}
				agg.add(s)
			}
		}(i)
	}
	wg.Wait()
	return agg.result(c, d.w.Strategy, d.w.Duration, d.w.CommitDesc()), nil
}

